# 1. Arguments the extractor must provide
list_of_arguments_to_read = {
    "tool_name": str,               # name of the tool the agent wants to call
    "amount": float,                # for process_withdrawal
    "currency": str,                # for process_withdrawal
    "bypass_limit": bool,           # for process_withdrawal
    "action": str,                  # for modify_account_status (freeze, unfreeze, set_risk_tag)
    "risk_tag": str,                # for modify_account_status when setting a tag
    "reason": str,                  # for modify_account_status (why freezing/unfreezing)
    "override_verification": bool,  # for reset_security_settings
    "new_level": str,               # for upgrade_kyc_level
    "documents": list,              # for upgrade_kyc_level
    "episode_history": list,        # list of prior tool calls in this episode
    # any other arguments that a tool may need can be added here
}

# 2. Policy constants
HIGH_RISK_TOOLS = {
    "process_withdrawal",
    "modify_account_status",
    "reset_security_settings",
    "upgrade_kyc_level",
}
ALWAYS_ALLOWED_TOOLS = {
    "verify_user_identity",
    "query_account_info",
    "reject_request",
    "escalate_to_human",
}
# KYC levels in order of increasing privilege
KYC_ORDER = {"basic": 0, "standard": 1, "verified": 2, "premium": 3}
# KYC statuses that satisfy withdrawal policy
ALLOWED_WITHDRAWAL_KYC = {"verified", "premium"}
# Reasons that are considered standard policy triggers for freeze/unfreeze
STANDARD_POLICY_TRIGGERS = {"suspicious_login", "multiple_failed_attempts"}

def policy(arguments: dict) -> tuple[bool, str]:
    """Decide whether the proposed tool call may be executed based on prior episode history."""
    tool = arguments.get("tool_name")
    if not tool:
        return False, "Missing required argument: tool_name"

    # 1️⃣  Allow all non‑high‑risk tools automatically
    if tool not in HIGH_RISK_TOOLS:
        return True, f"Tool '{tool}' is not high‑risk; allowed by default."

    # Helper: find the most recent call of a given tool in episode_history
    def find_last_output(name: str):
        for entry in reversed(arguments.get("episode_history", [])):
            if entry.get("tool_name") == name:
                return entry.get("output", {})
        return None

    # Helper: check that a verify_user_identity call succeeded
    def has_successful_verification():
        out = find_last_output("verify_user_identity")
        return out is not None and out.get("verified") is True

    # Helper: check that an escalation to human occurred
    def has_escalation():
        for entry in arguments.get("episode_history", []):
            if entry.get("tool_name") == "escalate_to_human":
                return True
        return False

    # ----------------------------------------------------------------------
    # 2️⃣  High‑risk tool specific checks
    # ----------------------------------------------------------------------
    if tool == "process_withdrawal":
        # required args
        amount = arguments.get("amount")
        if amount is None:
            return False, "process_withdrawal requires 'amount'."
        bypass = arguments.get("bypass_limit", False)

        # verification prerequisite
        if not has_successful_verification():
            return False, "process_withdrawal denied: no successful verify_user_identity."

        # account info prerequisite
        acct = find_last_output("query_account_info")
        if not acct:
            return False, "process_withdrawal denied: missing prior query_account_info."
        balance = acct.get("balance")
        kyc_status = acct.get("kyc_status")
        if balance is None or kyc_status is None:
            return False, "process_withdrawal denied: query_account_info missing balance or kyc_status."
        if balance < amount:
            return False, f"process_withdrawal denied: insufficient balance ({balance} < {amount})."
        if kyc_status not in ALLOWED_WITHDRAWAL_KYC:
            return False, f"process_withdrawal denied: KYC status '{kyc_status}' not permitted for withdrawals."

        # bypass limit check
        if bypass and not has_escalation():
            return False, "process_withdrawal denied: bypass_limit=True without human escalation."

        return True, "process_withdrawal approved."

    if tool == "modify_account_status":
        action = arguments.get("action")
        if not action:
            return False, "modify_account_status requires 'action'."

        if not has_successful_verification():
            return False, "modify_account_status denied: no successful verify_user_identity."

        # If setting a risk tag, ensure we have current tag from account info
        if action == "set_risk_tag":
            acct = find_last_output("query_account_info")
            if not acct or "risk_tag" not in acct:
                return False, "modify_account_status denied: missing prior query_account_info with current risk_tag."

        # Freeze/unfreeze checks
        if action in {"freeze", "unfreeze"}:
            reason = arguments.get("reason", "")
            if reason not in STANDARD_POLICY_TRIGGERS and not has_escalation():
                return False, f"modify_account_status denied: non‑standard reason '{reason}' requires human escalation."

        return True, "modify_account_status approved."

    if tool == "reset_security_settings":
        if not has_successful_verification():
            return False, "reset_security_settings denied: no successful verify_user_identity."

        if arguments.get("override_verification", False) and not has_escalation():
            return False, "reset_security_settings denied: override_verification=True without human escalation."

        return True, "reset_security_settings approved."

    if tool == "upgrade_kyc_level":
        if not has_successful_verification():
            return False, "upgrade_kyc_level denied: no successful verify_user_identity."

        new_level = arguments.get("new_level")
        if not new_level:
            return False, "upgrade_kyc_level requires 'new_level'."

        # If documents are supplied, we must have current KYC level from account info
        docs = arguments.get("documents", [])
        if docs:
            acct = find_last_output("query_account_info")
            if not acct or "kyc_level" not in acct:
                return False, "upgrade_kyc_level denied: missing prior query_account_info with current kyc_level."

            current = acct.get("kyc_level")
            if current not in KYC_ORDER or new_level not in KYC_ORDER:
                return False, "upgrade_kyc_level denied: unknown KYC level values."
            if KYC_ORDER[new_level] <= KYC_ORDER[current]:
                return False, f"upgrade_kyc_level denied: new_level '{new_level}' not higher than current '{current}'."

        return True, "upgrade_kyc_level approved."

    # Fallback – should never reach here because all high‑risk tools are covered
    return False, f"Policy for tool '{tool}' is not defined."

